# Illustrative sketch of the logic, not the production code (that belongs to the company)
for batch in chunk(parcels, size=BATCH):
    responses = geocode_batch([p.centroid for p in batch])   # rate-limited, retried
    for parcel, resp in zip(batch, responses):
        parts  = parse_components(resp)                        # number, street, postcode, city
        addr   = clean(parts, rules=CITY_RULES[city])          # local formats, casing, abbreviations
        issues = validate(addr, parcel)                        # missing number, outside parcel, duplicate
        parcel.address = addr
        if issues:
            review_queue.add(parcel, issues)                   # only exceptions reach a person
